const SKIP_IF_EXISTS = ['Base_Contract','Directory','Policy_Registry','KB_Gaps','Eval_Suite','Roster_v2','Handoffs','KB_Map'];

function setupUpgradePack() {
  if (!_isAdminUser_()) { _toast_('Admin only'); return; }
  const book = ss_();
  const report = [];
  Object.keys(UPGRADE_DATA).forEach(function (name) {
    const rows = UPGRADE_DATA[name];
    let sh = book.getSheetByName(name);
    if (sh && SKIP_IF_EXISTS.indexOf(name) !== -1) { report.push(name + ': exists, left untouched'); return; }
    if (!sh) sh = book.insertSheet(name); else sh.clear();
    const width = rows.reduce(function (m, r) { return Math.max(m, r.length); }, 0);
    const grid = rows.map(function (r) { const c = r.slice(); while (c.length < width) c.push(''); return c; });
    const rng = sh.getRange(1, 1, grid.length, width);
    rng.setNumberFormat('@');            // keep text that starts with '=' as text
    rng.setValues(grid);
    sh.setFrozenRows(1);
    report.push(name + ': wrote ' + grid.length + ' rows');
  });
  Logger.log(report.join('\n'));
  return report;
}

function promoteAgentsV2() {
  if (!_isAdminUser_()) { _toast_('Admin only'); return; }
  const book = ss_();
  const agents = book.getSheetByName('Agents');
  const staged = book.getSheetByName('Agents_v2_staging');
  if (!agents || !staged) throw new Error('Agents or Agents_v2_staging tab missing. Run setupUpgradePack() first.');
  const stamp = Utilities.formatDate(new Date(), 'UTC', 'yyyyMMdd_HHmm');
  agents.copyTo(book).setName('Agents_backup_' + stamp);

  const a = agents.getDataRange().getValues();
  const s = staged.getDataRange().getValues();
  const ah = a[0].map(String), sh = s[0].map(String);
  const col = function (h, name) { return h.indexOf(name); };
  const aSlug = col(ah, 'slug'), sSlug = col(sh, 'slug');
  if (aSlug < 0 || sSlug < 0) throw new Error('slug column not found');
  const UPDATE = ['personality', 'notes', 'skills'];
  const index = {};
  for (let i = 1; i < a.length; i++) index[String(a[i][aSlug]).trim()] = i + 1;

  let updated = 0, added = 0;
  for (let r = 1; r < s.length; r++) {
    const slug = String(s[r][sSlug]).trim();
    if (!slug) continue;
    if (index[slug]) {
      UPDATE.forEach(function (h) {
        const ac = col(ah, h), sc = col(sh, h);
        if (ac >= 0 && sc >= 0) agents.getRange(index[slug], ac + 1).setValue(s[r][sc]);
      });
      updated++;
    } else {
      const row = ah.map(function (h) { const sc = col(sh, h); return sc >= 0 ? s[r][sc] : ''; });
      agents.appendRow(row);
      added++;
    }
  }
  const msg = 'Backup: Agents_backup_' + stamp + ' | updated ' + updated + ' | added ' + added;
  Logger.log(msg);
  return msg;
}
